"use client";

import * as React from "react";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { Building2, Check } from "lucide-react";
import { cn } from "@vegastack/design";
import {
  ACCENTS,
  isAccentId,
  type AccentId,
} from "@vegastack/design-tokens/accents";
import { RadioGroup } from "@/components/ui/radio-group";

/** The radio value of the option that follows the workspace, whose `value` is `null`. */
const FOLLOW = "workspace";

/** Props accepted by `AccentPicker`. */
export interface AccentPickerProps extends Omit<
  React.ComponentProps<typeof RadioGroup>,
  "value" | "defaultValue" | "onValueChange" | "children"
> {
  /** The chosen accent; `null` follows the workspace (only with `workspaceAccent`). */
  value: AccentId | null;
  /** Called with the new choice; `null` when the workspace's is chosen. */
  onValueChange: (value: AccentId | null) => void;
  /**
   * The workspace's own accent. Given, a first option follows it; left out, only the colours show.
   * @default undefined
   */
  workspaceAccent?: AccentId;
  /**
   * The words on the option that follows the workspace.
   * @default "Workspace theme"
   */
  workspaceLabel?: string;
  /**
   * Other names for the colours, by id.
   * @default undefined
   */
  labels?: Partial<Record<AccentId, string>>;
}

function Option({
  value,
  accent,
  label,
  name,
  className,
}: {
  value: string;
  accent: AccentId;
  label: string;
  /** The accessible name, where it says more than the label. */
  name?: string;
  className?: string;
}) {
  const id = React.useId();
  return (
    <RadioPrimitive.Root
      value={value}
      data-slot="accent-picker-option"
      // Inside a `Field` Base UI would name every option after the field; an option is its colour.
      render={(optionProps: React.ComponentProps<"span">) => (
        <span
          {...optionProps}
          aria-label={name}
          aria-labelledby={name ? undefined : id}
        />
      )}
      className={cn(
        "group/accent-option flex min-h-22 min-w-0 cursor-pointer flex-col items-center gap-2 rounded-item px-0.5 py-3 text-center text-xs select-none state-layer data-disabled:cursor-not-allowed data-disabled:opacity-50 @min-[40rem]/accent-picker:text-sm",
        className,
      )}
    >
      <span
        data-slot="accent-picker-swatch"
        // Only the swatch wears the colour; the name and the focus tint stay the page's.
        data-accent={accent}
        className="grid size-10 flex-none place-items-center rounded-full bg-primary text-primary-foreground forced-color-adjust-none"
      >
        {value === FOLLOW ? (
          <Building2
            aria-hidden="true"
            className="col-start-1 row-start-1 size-4.5 group-data-checked/accent-option:hidden"
          />
        ) : null}
        <Check
          data-slot="accent-picker-check"
          aria-hidden="true"
          strokeWidth={2.5}
          className="col-start-1 row-start-1 hidden size-4.5 group-data-checked/accent-option:block"
        />
      </span>
      <span id={id} className="group-data-checked/accent-option:font-medium">
        {label}
      </span>
    </RadioPrimitive.Root>
  );
}

/**
 * `AccentPicker` — the seven colours as a radio group of round swatches with their names. With
 * `workspaceAccent` a first option, marked with a building, follows the workspace (its value is
 * `null`). The chosen one shows a check on its colour and a heavier name, never an outline; arrow
 * keys move the choice. It applies nothing itself: call `setAccent` and save in `onValueChange`.
 * Give it a label; on its own it is named "Colour".
 *
 * @example
 * <AccentPicker
 *   value={own}
 *   workspaceAccent={workspace.accent}
 *   onValueChange={(next) => {
 *     setAccent(next ?? workspace.accent);
 *     void save(next);
 *   }}
 * />
 */
export function AccentPicker({
  value,
  onValueChange,
  workspaceAccent,
  workspaceLabel = "Workspace theme",
  labels,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  ...props
}: AccentPickerProps) {
  const name = (id: AccentId) =>
    labels?.[id] ?? ACCENTS.find((accent) => accent.id === id)!.label;
  return (
    <div data-slot="accent-picker" className="@container/accent-picker w-full">
      <RadioGroup
        {...props}
        aria-label={ariaLabel ?? (ariaLabelledby ? undefined : "Colour")}
        aria-labelledby={ariaLabelledby}
        value={value ?? FOLLOW}
        onValueChange={(next) => onValueChange(isAccentId(next) ? next : null)}
        className={cn(
          "auto-rows-fr grid-cols-2 gap-1 @min-[17rem]/accent-picker:grid-cols-4 @min-[40rem]/accent-picker:gap-2",
          workspaceAccent
            ? "@min-[40rem]/accent-picker:grid-cols-8"
            : "@min-[40rem]/accent-picker:max-w-204 @min-[40rem]/accent-picker:grid-cols-7",
          className,
        )}
      >
        {workspaceAccent ? (
          <Option
            value={FOLLOW}
            accent={workspaceAccent}
            label={workspaceLabel}
            name={`${workspaceLabel}, ${name(workspaceAccent)}`}
          />
        ) : null}
        {ACCENTS.map(({ id }) => (
          <Option
            key={id}
            value={id}
            accent={id}
            label={name(id)}
            // Seven in two columns: the last takes its whole row, so nothing is left hanging.
            className={
              workspaceAccent
                ? undefined
                : "last-of-type:col-span-2 @min-[17rem]/accent-picker:last-of-type:col-span-1"
            }
          />
        ))}
      </RadioGroup>
    </div>
  );
}

// @vegastack accent@0.136.4 sha256-QwjkAL5uCfoMTZr3i7Vb6zDPebvAxD3MTomcB+9Z500=

import * as React from "react";
import { Inbox, ListTodo } from "lucide-react";
import { cn, proseClassName } from "@vegastack/design";
import type { AccentId } from "@vegastack/design-tokens/accents";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { NavTree, NavTreeItem, NavTreeSection } from "@/components/ui/nav-tree";
import { NotificationDot } from "@/components/ui/notification-dot";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { StatusIcon } from "@/components/ui/status-icon";
import { Switch } from "@/components/ui/switch";

/** The words in `AccentPreview`, for translation. */
export interface AccentPreviewLabels {
  tasks: string;
  newTask: string;
  taskDone: string;
  taskOpen: string;
  myTasks: string;
  inbox: string;
  linkBefore: string;
  link: string;
  badge: string;
  notify: string;
  choice: string;
  otherChoice: string;
  cancel: string;
  save: string;
  same: string;
  overdue: string;
  inProgress: string;
  done: string;
  remove: string;
  retry: string;
}

const LABELS: AccentPreviewLabels = {
  tasks: "My tasks",
  newTask: "New task",
  taskDone: "Pick two rug options",
  taskOpen: "Update the product sheet",
  myTasks: "My tasks",
  inbox: "Inbox",
  linkBefore: "Priya shared the",
  link: "lighting plan",
  badge: "New",
  notify: "Notify the team",
  choice: "Everyone in Design",
  otherChoice: "Only me",
  cancel: "Cancel",
  save: "Save",
  same: "Stays the same with every colour",
  overdue: "Overdue",
  inProgress: "In progress",
  done: "Done",
  remove: "Delete",
  retry: "Retry",
};

/** Props accepted by `AccentPreview`. */
export interface AccentPreviewProps extends Omit<
  React.ComponentProps<"div">,
  "children"
> {
  /** The accent it is drawn in, whatever the page wears. Left out, it wears the page's. @default undefined */
  accent?: AccentId;
  /** Other words, for translation. @default undefined */
  labels?: Partial<AccentPreviewLabels>;
}

const CARD =
  "flex min-w-0 flex-col gap-3 rounded-card border border-border bg-background p-4 text-sm";
const ROW = "flex min-w-0 items-center gap-2";

/**
 * `AccentPreview` — what a colour changes and what it never does, drawn with the real components.
 * It is a picture: nothing in it takes the pointer or the keyboard, and assistive technology skips it.
 *
 * @example
 * <AccentPreview accent={own ?? workspace.accent} />
 */
export function AccentPreview({
  accent,
  labels,
  className,
  ...props
}: AccentPreviewProps) {
  const words = { ...LABELS, ...labels };
  return (
    <div
      {...props}
      data-slot="accent-preview"
      data-accent={accent}
      aria-hidden="true"
      inert
      className={cn("@container/accent-preview w-full select-none", className)}
    >
      <div className="grid gap-3 @min-[34rem]/accent-preview:grid-cols-2 @min-[68rem]/accent-preview:grid-cols-4">
        <div className={CARD}>
          <div className={cn(ROW, "justify-between")}>
            <span className="font-medium">{words.tasks}</span>
            <Button size="sm">{words.newTask}</Button>
          </div>
          <div className={ROW}>
            <Checkbox checked readOnly />
            {words.taskDone}
          </div>
          <div className={ROW}>
            <Checkbox checked={false} readOnly />
            {words.taskOpen}
          </div>
        </div>
        <div className={CARD}>
          <NavTree aria-label={words.tasks}>
            <NavTreeSection>
              <NavTreeItem icon={<ListTodo />} label={words.myTasks} active />
              <NavTreeItem
                icon={<Inbox />}
                label={
                  <span className={ROW}>
                    {words.inbox}
                    <NotificationDot />
                  </span>
                }
              />
            </NavTreeSection>
          </NavTree>
          <div className={cn(ROW, "flex-wrap justify-between")}>
            <span className={proseClassName}>
              {words.linkBefore} <a href="#accent-preview">{words.link}</a>
            </span>
            <Badge>{words.badge}</Badge>
          </div>
        </div>
        <div className={CARD}>
          <div className={ROW}>
            <Switch checked readOnly />
            {words.notify}
          </div>
          <RadioGroup value="all" readOnly className="gap-2">
            <div className={ROW}>
              <RadioGroupItem value="all" />
              {words.choice}
            </div>
            <div className={ROW}>
              <RadioGroupItem value="me" />
              {words.otherChoice}
            </div>
          </RadioGroup>
          <div className={ROW}>
            <Button size="sm" variant="outline">
              {words.cancel}
            </Button>
            <Button size="sm">{words.save}</Button>
          </div>
        </div>
        <div className={CARD}>
          <span className="text-xs text-muted-foreground">{words.same}</span>
          <div className={cn(ROW, "flex-wrap gap-x-3")}>
            <span className="text-destructive-text">{words.overdue}</span>
            <span className="flex items-center gap-1.5">
              <StatusIcon status="progress" label="" />
              {words.inProgress}
            </span>
            <span className="flex items-center gap-1.5">
              <StatusIcon status="done" label="" />
              {words.done}
            </span>
          </div>
          <div className={ROW}>
            <Button size="sm" variant="destructive">
              {words.remove}
            </Button>
            <Button size="sm" variant="outline">
              {words.retry}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

// @vegastack accent@0.136.4 sha256-QwjkAL5uCfoMTZr3i7Vb6zDPebvAxD3MTomcB+9Z500=

import {
  ACCENT_COOKIE,
  ACCENTS,
  DEFAULT_ACCENT,
} from "@vegastack/design-tokens/accents";

/* ---
The accent's before-paint script, in a file of its own with no client imports: the root layout
renders it on every page, signed out and public ones included, so importing it must not pull any
client graph into those pages.
--- */

/** A JS literal that cannot close the inline `<script>` it is written into. */
function scriptLiteral(value: unknown) {
  return JSON.stringify(value).replace(/</g, "\\u003c");
}

/** Props accepted by `AccentScript`. */
export interface AccentScriptProps {
  /**
   * Paths whose pages never wear the person's accent (sign-in, docs, a public link with its own
   * `AccentScope`): the path itself and everything under it.
   * @default []
   */
  skip?: readonly string[];
  /** The request's nonce, under a nonce-based Content Security Policy. @default undefined */
  nonce?: string;
}

/**
 * `AccentScript` — put it in `<head>`. Before the first paint it reads the `vs_accent` cookie and,
 * when it is one of the seven accent ids, marks `<html>` with `data-accent`, so even a cached page
 * paints the person's colour with no flash. Black is no mark at all. A missing, unknown or blocked
 * cookie leaves Black. The host `<html>` needs `suppressHydrationWarning`.
 *
 * @example
 * <head><AccentScript skip={["/login", "/docs", "/s"]} /></head>
 */
export function AccentScript({ skip = [], nonce }: AccentScriptProps) {
  const ids = ACCENTS.map(({ id }) => id).filter((id) => id !== DEFAULT_ACCENT);
  const source = `(function(n,v,s){try{var p=location.pathname,i,k,j;for(i=0;i<s.length;i++)if(p===s[i]||p.indexOf(s[i].replace(/\\/$/,"")+"/")===0)return;k=document.cookie.split(/;\\s*/);for(i=0;i<k.length;i++){j=k[i].indexOf("=");if(j>0&&k[i].slice(0,j)===n){if(v.indexOf(k[i].slice(j+1))>=0)document.documentElement.setAttribute("data-accent",k[i].slice(j+1));return}}}catch(z){}})(${scriptLiteral(ACCENT_COOKIE)},${scriptLiteral(ids)},${scriptLiteral(skip)})`;
  return (
    <script
      data-slot="accent-script"
      nonce={nonce}
      suppressHydrationWarning
      dangerouslySetInnerHTML={{ __html: source }}
    />
  );
}
